pub struct Conn {
    log: Vec<String>,
}

#[derive(Debug, thiserror::Error)]
pub enum DbError {
    #[error("write conflict")]
    Conflict,
}

pub struct Tx<'c> {
    conn: &'c mut Conn,
}

impl<'c> Tx<'c> {
    pub fn execute(&mut self, sql: &str) -> Result<u64, DbError> {
        self.conn.log.push(sql.to_string());
        Ok(1)
    }

    pub fn commit(self) -> Result<(), DbError> {
        Ok(())
    }

    pub fn rollback(self) -> Result<(), DbError> {
        Ok(())
    }
}

pub struct Db {
    conn: Conn,
}

impl Db {
    pub fn begin(&mut self) -> Result<Tx<'_>, DbError> {
        Ok(Tx { conn: &mut self.conn })
    }
}

use crate::db::{Db, DbError};

pub fn seed(db: &mut Db, name: String) -> Result<(), DbError> {
    let mut tx = db.begin()?;
    tx.execute(&insert_sql(name))?;
    tx.execute("update counters set n = n + 1")?;
    tx.commit()
}

fn insert_sql(name: String) -> String {
    format!("insert into users (name) values ('{name}')")
}

