where
    F: FnOnce(&'a mut Tx<'a>) -> Result<T, DbError>,
{
    let mut tx = self.begin()?;
    match f(&mut tx) {
        Ok(value) => {
            tx.commit()?;
            Ok(value)
        }
        Err(error) => {
            tx.rollback()?;
            Err(error)
        }
    }
}

