use futures::future::BoxFuture;

pub async fn transaction<T, F>(&mut self, mut f: F) -> Result<T, DbError>
where
    F: for<'a, 'b> FnMut(&'a mut Tx<'b>) -> BoxFuture<'a, Result<T, DbError>>,
{
    for attempt in 0..3 {
        let mut tx = self.begin()?;
        match f(&mut tx).await {
            Ok(value) => {
                tx.commit().await?;
                return Ok(value);
            }
            Err(DbError::Conflict) if attempt < 2 => tx.rollback().await?,
            Err(error) => {
                tx.rollback().await?;
                return Err(error);
            }
        }
    }
    Err(DbError::Conflict)
}
